<?php
namespace App\Support;
use App\Models\{User,Apprentice,LearningTask,ProgrammeOutcome,CohortForecast as Forecast};
use Illuminate\Support\Facades\DB;
class CohortForecasts {
 public const BASES=['Staff estimate','Employer-supported estimate','Approved plan reference'];
 public static function allowed(User $u,Apprentice $a):bool {return $u->active&&!AccountLifecycle::blocked($u)&&(LearningAccess::manager($u)||LearningAccess::tutor($u,$a));}
 public static function source(Apprentice $a):array {$outcome=ProgrammeOutcome::where('apprentice_id',$a->id)->first();$context=collect($outcome?->context??[])->only(['status','achievement','endDate','achievementDate','sourceRef'])->all();$plan=DeliveryPlan::approved($a);return ['hash'=>ReviewedImports::hash(['identity'=>$a->only(['id','programme_id','tutor_id','start_date','planned_end_date','version']),'outcome'=>$context,'plan'=>$plan,'tasks'=>LearningTask::where('apprentice_id',$a->id)->orderBy('id')->get(['id','status','version','due_date','submitted_at','template'])->map(fn($t)=>$t->only(['id','status','version','due_date','submitted_at'])+['kind'=>$t->template['kind']??'source-pending'])->all()]),'context'=>$context,'approved_plan'=>$plan];}
 public static function fields(Forecast $f):array {return $f->only(['apprentice_id','version','source_hash']);}
 public static function intact(Forecast $f):bool {try{return $f->details['fields']===self::fields($f)&&in_array($f->details['basis'],self::BASES,true);}catch(\Throwable){return false;}}
 public static function current(Forecast $f,array $source):bool {try{return self::intact($f)&&$f->source_hash===$source['hash']&&$f->details['review_on']>=today()->toDateString()&&$f->details['target_date']>=today()->toDateString()&&in_array($source['context']['status']??null,['Active','Break in learning'],true)&&filled($source['context']['sourceRef']??null);}catch(\Throwable){return false;}}
 public static function save(User $actor,int $auth,Apprentice $person,int $version,string $hash,string $target,string $review,string $basis,string $reference,string $reason):void {DB::transaction(function()use($actor,$auth,$person,$version,$hash,$target,$review,$basis,$reference,$reason):void {$u=PortalOperations::actor($actor,$auth);$a=Apprentice::whereKey($person->id)->lockForUpdate()->firstOrFail();abort_unless(self::allowed($u,$a),403);$source=self::source($a);if($hash!==$source['hash']||!in_array($basis,self::BASES,true)||!PortalOperations::reference($reference)||!PortalOperations::reference($reason)||!in_array($source['context']['status']??null,['Active','Break in learning'],true)||!filled($source['context']['sourceRef']??null)){CentrePlanning::fail('Use current active-programme context, a checked estimate basis and source/reason references.');}validator(['target'=>$target,'review'=>$review],['target'=>'required|date_format:Y-m-d|after_or_equal:today','review'=>'required|date_format:Y-m-d|after_or_equal:today|before_or_equal:target'])->validate();if($basis==='Approved plan reference'&&!$source['approved_plan']){CentrePlanning::fail('This estimate basis requires a current approved individual plan.');}$f=Forecast::whereKey($a->id)->lockForUpdate()->first();if(($f?->version??0)!==$version||$f&&!self::intact($f)){CentrePlanning::fail('Forecast changed or needs recovery; reload.');}$history=$f?->details['history']??[];if($f){$history[]=$f->details;unset($history[array_key_last($history)]['history']);}$f??=new Forecast(['apprentice_id'=>$a->id,'version'=>0]);$f->version++;$f->source_hash=$hash;$f->details=['fields'=>self::fields($f),'target_date'=>$target,'review_on'=>$review,'basis'=>$basis,'reference'=>$reference,'reason'=>$reason,'by'=>$u->id,'at'=>now()->toIso8601String(),'history'=>$history,'guaranteed_completion'=>false];$f->save();PortalOperations::event($u,'forecast',(string)$a->id,'forecast_recorded',['version'=>$f->version,'source_hash'=>$hash,'target_date'=>$target,'review_on'=>$review,'basis'=>$basis]);},3);}
}
